"""
MarketLens - Phase 07: Marketing KPIs
=======================================
Campaign ROI, CAC (customer acquisition cost), conversion rate, and revenue
contribution — joining marketing_campaigns to the customers each campaign
acquired (customers.acquisition_campaign_id) and the revenue those
customers went on to generate.
"""

from __future__ import annotations

import pandas as pd


def campaign_performance(campaigns: pd.DataFrame, customers: pd.DataFrame, orders: pd.DataFrame) -> pd.DataFrame:
    # Revenue generated by customers acquired through each campaign
    cust_revenue = (
        orders.groupby("customer_id")["gross_revenue"].sum().reset_index()
        .rename(columns={"gross_revenue": "customer_total_revenue"})
    )
    cust_with_rev = customers.merge(cust_revenue, on="customer_id", how="left")
    cust_with_rev["customer_total_revenue"] = cust_with_rev["customer_total_revenue"].fillna(0.0)

    acquired_revenue = (
        cust_with_rev.dropna(subset=["acquisition_campaign_id"])
        .groupby("acquisition_campaign_id")
        .agg(
            customers_acquired=("customer_id", "count"),
            revenue_from_acquired=("customer_total_revenue", "sum"),
        )
        .reset_index()
        .rename(columns={"acquisition_campaign_id": "campaign_id"})
    )

    out = campaigns.merge(acquired_revenue, on="campaign_id", how="left")
    out["customers_acquired"] = out["customers_acquired"].fillna(0).astype(int)
    out["revenue_from_acquired"] = out["revenue_from_acquired"].fillna(0.0)

    out["conversion_rate_pct"] = (
        out["customers_converted"] / out["customers_targeted"] * 100
    ).round(2)

    out["cac"] = (out["spend"] / out["customers_acquired"].replace(0, pd.NA)).round(2)

    out["roi_pct"] = (
        (out["revenue_from_acquired"] - out["spend"]) / out["spend"] * 100
    ).round(2)

    return out.sort_values("roi_pct", ascending=False)


def campaign_type_summary(campaign_perf: pd.DataFrame) -> pd.DataFrame:
    out = (
        campaign_perf.groupby("campaign_type")
        .agg(
            campaigns=("campaign_id", "count"),
            total_spend=("spend", "sum"),
            total_customers_acquired=("customers_acquired", "sum"),
            total_revenue_from_acquired=("revenue_from_acquired", "sum"),
            avg_conversion_rate_pct=("conversion_rate_pct", "mean"),
        )
        .reset_index()
    )
    out["blended_cac"] = (
        out["total_spend"] / out["total_customers_acquired"].replace(0, pd.NA)
    ).round(2)
    out["roi_pct"] = (
        (out["total_revenue_from_acquired"] - out["total_spend"]) / out["total_spend"] * 100
    ).round(2)
    out["avg_conversion_rate_pct"] = out["avg_conversion_rate_pct"].round(2)
    return out.sort_values("roi_pct", ascending=False)


def marketing_summary(campaigns: pd.DataFrame, customers: pd.DataFrame, orders: pd.DataFrame) -> dict:
    perf = campaign_performance(campaigns, customers, orders)
    total_spend = float(perf["spend"].sum())
    total_revenue_from_acquired = float(perf["revenue_from_acquired"].sum())
    total_acquired = int(perf["customers_acquired"].sum())
    total_targeted = int(campaigns["customers_targeted"].sum())
    total_converted = int(campaigns["customers_converted"].sum())

    return {
        "total_campaigns": int(len(campaigns)),
        "total_marketing_spend": round(total_spend, 2),
        "total_customers_targeted": total_targeted,
        "total_customers_converted": total_converted,
        "overall_conversion_rate_pct": round(total_converted / total_targeted * 100, 2) if total_targeted else 0.0,
        "total_customers_acquired_via_campaigns": total_acquired,
        "blended_cac": round(total_spend / total_acquired, 2) if total_acquired else 0.0,
        "revenue_from_campaign_acquired_customers": round(total_revenue_from_acquired, 2),
        "overall_roi_pct": round(
            (total_revenue_from_acquired - total_spend) / total_spend * 100, 2
        ) if total_spend else 0.0,
    }
